command:
$ErrorActionPreference="Stop"
$db=New-Object System.Data.OleDb.OleDbConnection('Provider=Search.CollatorDSO.1;Extended Properties="Application=Windows"')
$db.Open()
try {
 $pictures=("file:"+[Environment]::GetFolderPath("MyPictures").Replace("\","/").TrimEnd("/")+"/").Replace("'","''")
 $cases=@(
   @("all-edge","SELECT TOP 20 System.ItemUrl FROM SystemIndex WHERE System.FileName LIKE '%Microsoft Edge%'"),
   @("public-scope","SELECT TOP 20 System.ItemUrl FROM SystemIndex WHERE SCOPE='file:C:/Users/Public/Desktop/'"),
   @("public-edge","SELECT TOP 20 System.ItemUrl FROM SystemIndex WHERE SCOPE='file:C:/Users/Public/Desktop/' AND System.FileName LIKE '%Microsoft Edge%'"),
   @("pictures-scope","SELECT TOP 20 System.ItemUrl FROM SystemIndex WHERE SCOPE='"+$pictures+"'"),
   @("pictures-direct","SELECT TOP 20 System.ItemUrl FROM SystemIndex WHERE DIRECTORY='"+$pictures.TrimEnd("/")+"'")
 )
 foreach($c in $cases){
  $cmd=$db.CreateCommand();$cmd.CommandText=$c[1]
  try{$rd=$cmd.ExecuteReader();$n=0;while($rd.Read()){$n++};$rd.Close();Write-Host ("INDEX_PROBE_"+$c[0]+"="+$n)}
  catch{Write-Host ("INDEX_PROBE_"+$c[0]+"=ERROR:"+$_.Exception.GetType().Name)}
 }
}finally{$db.Close()}
Write-Host "INDEX_SQL_SCOPE_DIAG=PASS"
